pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testFuzz_property(uint64 _timestamp) public {
        vm.prank(address(0));
        try c.setL1BlockValues(1, _timestamp, 1, bytes32(0), 1, bytes32(0), 1, 1) {
            assertTrue(c.timestamp() == 0);
        } catch {
            assertTrue(true);
        }
    }
}
